package br.com.fiap.bank.plataforma.application.dto;
import br.com.fiap.bank.plataforma.domain.*; import java.math.BigDecimal; import java.time.LocalDateTime; public record SolicitacaoCreditoResponseDTO(Long id,String cpfCliente,String nomeCliente,String tipoCredito,BigDecimal valorSolicitado,Integer quantidadeParcelas,BigDecimal rendaMensal,Integer scoreCredito,StatusSolicitacao status,String parecerOperador,Boolean scrRestricoes,Integer scoreBureau,LocalDateTime dataSolicitacao,LocalDateTime dataAtualizacao) { public static SolicitacaoCreditoResponseDTO from(SolicitacaoCredito x){return new SolicitacaoCreditoResponseDTO(x.getId(),x.getCpfCliente(),x.getNomeCliente(),x.getTipoCredito(),x.getValorSolicitado(),x.getQuantidadeParcelas(),x.getRendaMensal(),x.getScoreCredito(),x.getStatus(),x.getParecerOperador(),x.getScrRestricoes(),x.getScoreBureau(),x.getDataSolicitacao(),x.getDataAtualizacao());} }
